SELECT CAST(COUNT(CASE WHEN a.los >= 7 THEN 1 END) AS FLOAT) / NULLIF(COUNT(*), 0) AS proportion_of_admissions_with_los_of_at_least_7_days, CAST(COUNT(CASE WHEN a.los >= 14 THEN 1 END) AS FLOAT) / NULLIF(COUNT(*), 0) AS proportion_of_admissions_with_los_of_at_least_14_days, percentile_cont(0.7) within GROUP (ORDER BY a.los) AS percentile_of_los_of_at_least_7_days FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN services s ON a.subject_id = s.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 49 AND 59 AND s.service_name = 'medicine' AND a.discharge_location IN ('home', 'hospice', 'in-hospital death');